        vm.label(TARGET, "Touch Token");
        spender = address(0xBEEF);
        vm.label(spender, "Spender");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Inject tokens to attacker (deal works on token contract balance mapping)
        deal(TARGET, attacker, 1000 * 1e18);

        // Verify attacker has tokens
        uint256 balance = touch.balanceOf(attacker);
        console.log("Attacker balance:", balance);

